class RichDramaMeta {
  final String ruTitle;
  final List<String> genres;
  final double? rating;
  final int episodes;
  final String poster;
  final String summary;
  final List<int> airDays;
  final String airTime;
  const RichDramaMeta({
    required this.ruTitle,
    this.genres = const <String>[],
    this.rating,
    this.episodes = 0,
    this.poster = '',
    this.summary = '',
    this.airDays = const <int>[],
    this.airTime = '21:50',
  });
}

